    ctx.fillStyle = '#fff'; ctx.font = 'bold 13px ui-monospace,"Courier New",monospace';
    ctx.fillText(venceu ? 'VOCÊ CHEGOU À PRAÇA DE LÍDICE' : encerrado ? 'TOQUE PARA TENTAR DE NOVO' : '3 LUGARES · 1 TRAJETO · SEM REPETIR', W / 2, 193);
